param([int]$Frame = 1200)
$ErrorActionPreference='Stop';$Lab='D:\DLSSNR-Lab';$Input=Join-Path $Lab "ffx-color-$Frame-block56-corrected.f32";$Shifts=@{57=0;58=1;59=3;60=2;61=0}
